#Requires -Version 7.0
# Review step 3: list Global then Workspace memories via the Claude plugin wrapper.
# PRIVATE-MEMORY-REFERENCE-007 is removed from list.items BEFORE anything is rendered; it is never fetched individually.
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$plugin = '[HOME]/github/mcpserver-claude-code-plugin'
$ws = '[HOME]/github/WordGame/.mcpServer/wordpairs'
$wrapper = Join-Path $plugin 'lib/Invoke-McpPlugin.ps1'
Set-Location -LiteralPath $ws
. (Join-Path $plugin 'lib/yaml-object-mutation.ps1')
Import-McpYamlSerializer
$bom = [string][char]0xFEFF

function Get-Prop {
    param($Obj, [string]$Name)
    if ($null -eq $Obj) { return $null }
    if ($Obj -is [System.Collections.IDictionary]) { if ($Obj.Contains($Name)) { return $Obj[$Name] } else { return $null } }
    $p = $Obj.PSObject.Properties[$Name]
    if ($p) { return $p.Value }
    return $null
}

foreach ($scope in @('Global', 'Workspace')) {
    $paramsObject = [ordered]@{ scope = $scope }
    $raw = & $wrapper -Command Invoke -Method 'workflow.memory.list' -ParamsObject $paramsObject -WorkspacePath $ws -PluginRoot $plugin 2>$null
    $text = ($raw | Out-String).Replace($bom, '')
    $doc = $null
    try { $doc = ConvertFrom-Yaml -Yaml $text -ErrorAction Stop } catch { $doc = $null }
    if ($null -eq $doc) {
        Write-Output ("SCOPE {0}: UNPARSEABLE response length={1}; not rendered (could contain PRIVATE-MEMORY-REFERENCE-007)." -f $scope, $text.Length)
        continue
    }
    $payload = Get-Prop $doc 'payload'
    $result = Get-Prop $payload 'result'
    if ($null -eq $result) { $result = Get-Prop $doc 'result' }
    $items = Get-Prop $result 'items'
    if ($null -eq $items) { $items = Get-Prop $result 'memories' }
    if ($null -eq $items) {
        $keys = if ($result -is [System.Collections.IDictionary]) { $result.Keys -join ',' } else { '' }
        $type = Get-Prop $doc 'type'
        Write-Output ("SCOPE {0}: no items collection (type={1}; resultKeys={2})" -f $scope, $type, $keys)
        if ($type -eq 'error') { Write-Output ("ERROR: {0}" -f ((Get-Prop $payload 'message'))) }
        continue
    }
    $all = @($items)
    $filtered = @($all | Where-Object { [string](Get-Prop $_ 'id') -ne 'PRIVATE-MEMORY-REFERENCE-007' })
    $excluded = $all.Count - $filtered.Count
    $total = Get-Prop $result 'totalCount'
    Write-Output ("SCOPE {0}: returned={1} excludedProcess007={2} rendered={3} totalCount={4}" -f $scope, $all.Count, $excluded, $filtered.Count, $total)
    foreach ($m in ($filtered | Sort-Object { [string](Get-Prop $_ 'id') })) {
        Write-Output ("==== {0} [{1}] scope={2}" -f (Get-Prop $m 'id'), (Get-Prop $m 'category'), (Get-Prop $m 'scope'))
        Write-Output ([string](Get-Prop $m 'text'))
    }
}

