258	    # TR-MCP-REPL-011: persist an explicit valid sessionId into session-state.yaml instead of the
259	    # historical no-op, so an explicit openSession can recover a bad/rotated local session id
260	    # (BUG-TRIAGE-085; previously documented as a gap in GAPS.md).
261	    param(
262	        [string]$ParamsYaml,
263	        [string]$CacheDir = '',
264	        [string]$SessionId = '',
265	        [string]$RootSessionId = ''
266	    )
267	    if (-not [string]::IsNullOrWhiteSpace($CacheDir) -and -not [string]::IsNullOrWhiteSpace($SessionId)) {
268	        Write-ReplStickySessionState -CacheDir $CacheDir -RootSessionId $RootSessionId -SessionId $SessionId | Out-Null
